head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS11201.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_ClickDataCheck = function(vDelistCd) {
    if (vDelistCd == 01 || vDelistCd == 02) {
        $c.win.alert("만기상환이나 전액중도상환은 자동 상장폐지로 처리됩니다. 다시 선택하십시오.");
        return false;
    }
    return true;
};
scwin.fn_CheckActiv = function(ACTIV_YN) {
    if (ACTIV_YN == 'N') {
        var output = '비활성화된 코드입니다. ';
        output += '\n' + '활성 <-> 비활성 변경시 시스템관리자에게 직접 연락하세요';
        $c.win.alert(output);
        return false;
    }
    return true;
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_List); //패널라운드처리
    //파라미터추출
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        var url = "/listingCommon.do?method=listGeneralForDynamicName";
        url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
        url += "&outputMessageId=BNS_DELIST_RSN_SEL";
        url += "&queryId=lds.stf.bnsisuchg.select.listDelistRsn";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List.DataID = encodeURI(url);
        dts_List.Reset();
    }
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    var gDelistCd = dts_List.getCellData(row, "BND_DELIST_CD");
    var gActivYn = dts_List.getCellData(row, "ACTIV_YN");
    if (scwin.fn_ClickDataCheck(gDelistCd) == false) return;
    if (!scwin.fn_CheckActiv(gActivYn)) return;
    var arrPar = new Array();
    arrPar[0] = {
        BND_DELIST_CD: gDelistCd,
        DELIST_RSN_DTL: dts_List.getCellData(row, "DELIST_RSN_DTL"),
        MEMO: dts_List.getCellData(row, "MEMO")
    };
    scwin.fn_SetPar(arrPar);
    await $c.frame.CloseFrame();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
